From 08fdf425f5de7b58b4da1b71500692625dd59065 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 01:38:57 +0100
Subject: [PATCH] explorer: only reopen Panel Settings when the sidebar came
 from there

Closing the Widgets sidebar opened from a panel's context menu opened
Panel Settings, which is only right when it was opened from there. Track
that case and otherwise exit edit mode, as closing Panel Settings does.

BUG: 522315
---
 .../configuration/PanelConfiguration.qml      |  2 +-
 .../contents/explorer/WidgetExplorer.qml      | 19 ++++++++++++++-----
 desktoppackage/contents/views/Desktop.qml     |  1 +
 3 files changed, 16 insertions(+), 6 deletions(-)

diff --git a/desktoppackage/contents/configuration/PanelConfiguration.qml b/desktoppackage/contents/configuration/PanelConfiguration.qml
index cb897a1f04..cffe855c57 100644
--- a/desktoppackage/contents/configuration/PanelConfiguration.qml
+++ b/desktoppackage/contents/configuration/PanelConfiguration.qml
@@ -140,8 +140,8 @@ ColumnLayout {
                         text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:menu add a widget", "Widgets…")
                         icon.name: "view-group-symbolic"
                         onClicked: {
-                            configDialog.close()
                             configDialog.showAddWidgetDialog()
+                            configDialog.close()
                         }
                     }
                 }
diff --git a/desktoppackage/contents/explorer/WidgetExplorer.qml b/desktoppackage/contents/explorer/WidgetExplorer.qml
index 3a4e1ac3e8..398e47eaf0 100644
--- a/desktoppackage/contents/explorer/WidgetExplorer.qml
+++ b/desktoppackage/contents/explorer/WidgetExplorer.qml
@@ -57,6 +57,8 @@ PC3.Page {

     property bool draggingWidget: false

+    property bool openedFromPanelSettings: false
+
     signal closed()

     PlasmaCore.EdgeEventForwarder {
@@ -66,11 +68,18 @@ PC3.Page {
     }

     onClosed: {
-        // If was called from a panel, open the panel config
-        if (root.widgetExplorer.containment &&
-            root.widgetExplorer.containment.containmentType == 1 &&
-            !root.widgetExplorer.containment.userConfiguring) {
-            root.widgetExplorer.containment.internalAction("configure").trigger()
+        const containment = root.widgetExplorer.containment;
+        if (!containment || containment.containmentType != 1) {
+            return;
+        }
+        if (openedFromPanelSettings) {
+            // Go back to the panel config we were called from
+            if (!containment.userConfiguring) {
+                containment.internalAction("configure").trigger()
+            }
+        } else if (!containment.corona.enteredEditModeViaDesktop()) {
+            // Called from the panel's context menu: leave edit mode, like closing the panel config does
+            containment.corona.editMode = false
         }
     }

diff --git a/desktoppackage/contents/views/Desktop.qml b/desktoppackage/contents/views/Desktop.qml
index 1be09364ef..8290d27baa 100644
--- a/desktoppackage/contents/views/Desktop.qml
+++ b/desktoppackage/contents/views/Desktop.qml
@@ -47,6 +47,7 @@ Item {
             sidePanelStack.setSource(Qt.resolvedUrl("../explorer/WidgetExplorer.qml"), {
                 containment,
                 sidePanel,
+                openedFromPanelSettings: containment?.userConfiguring ?? false,
             });
         }
     }
-- 
